# Build the Multishine Nintendont STUB: the one file copied to SD:/apps/Nintendont-Multishine/boot.dol by hand.
#   build_stub.sh SHELL_DOL OUT_DIR [--devkey]
# SHELL_DOL = the loader DOL of build_wii.sh ($VBBA_OUT/shell.dol); it is embedded as the fallback shell (checked against the stub's DOL rules first).  OUT_DIR gets boot.dol (the stub),
# icon.png and meta.xml (generated by hbc/gen_hbc_assets.py).  --devkey adds the published RFC 8032 test key (LAB builds only; the release stub never has it).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../.." && pwd)"
shell="${1:?SHELL_DOL}"; out="${2:?OUT_DIR}"; dev="${3:-}"
export DEVKITPRO=${DEVKITPRO:-/opt/devkitpro}; export DEVKITPPC=${DEVKITPPC:-$DEVKITPRO/devkitPPC}
cc="$DEVKITPPC/bin/powerpc-eabi-gcc"; e2d="$DEVKITPRO/tools/bin/elf2dol"
[[ -x "$cc" && -x "$e2d" ]] || { echo "devkitPPC / elf2dol not found under $DEVKITPRO"; exit 1; }
python3.14 "$root/tools/card/shl_data.py" dolcheck "$shell" | grep -q '^ok$' || { echo "the shell DOL fails the stub's rules"; exit 1; }
t="$(mktemp -d)"; trap 'rm -rf "$t"' EXIT
mkdir -p "$t/loader/source" "$out"
python3.14 "$root/offline/nintendont-vbba/ota/stage_loader.py" "$root" "$t" ${dev:+--devkey} >/dev/null     # keys header + core + crypto into $t/loader/source
src="$t/loader/source"
cp "$here/stub_main.c" "$here/tramp.S" "$here/shell_dol.S" "$src/"
if [[ -n "${MS_STUB_TEST:-}" ]]; then MACH="-DGEKKO -mogc -mcpu=750 -meabi -mhard-float -DMS_STUB_TEST=1"; LIBS="-L$DEVKITPRO/libogc/lib/cube -logc -lm"     # emulator test build (GameCube, no SD): tests/chain_test.sh
else MACH="-DGEKKO -mrvl -mcpu=750 -meabi -mhard-float"; LIBS="-L$DEVKITPRO/libogc/lib/wii -lfat -logc -lm"; fi
INC="-I$src -I$DEVKITPRO/libogc/include"
CF="-std=gnu99 -O2 -Wall -Wextra -Wno-unused-parameter $MACH $INC ${MS_STUB_NOSD:+-DMS_STUB_NOSD=1}"   # MS_STUB_NOSD=1: diagnostic builds A (no SD access in the stub)
objs=()
for f in stub_main.c ms_ota_core.c mw2_crypto.c ms_sha256.c; do "$cc" $CF -c "$src/$f" -o "$t/${f%.c}.o"; objs+=("$t/${f%.c}.o"); done
"$cc" $MACH -mregnames -D_LANGUAGE_ASSEMBLY -c "$src/tramp.S" -o "$t/tramp.o"
"$cc" $MACH $INC -DSHELL_DOL_PATH="\"$shell\"" -c "$src/shell_dol.S" -o "$t/shell_dol.o"
"$cc" -g $MACH -o "$t/stub.elf" "${objs[@]}" "$t/tramp.o" "$t/shell_dol.o" $LIBS
"$e2d" "$t/stub.elf" "$out/boot.dol"
d="$(dirname "$shell")"
python3.14 "$root/offline/nintendont-vbba/hbc/gen_hbc_assets.py" "$out" >/dev/null     # the Homebrew Channel entry is ours: icon.png (navy + our mark) and meta.xml, generated (the loader rewrites meta.xml itself at every start)
echo "stub: $(stat -f %z "$out/boot.dol") bytes -> $out/boot.dol (embedded shell $(stat -f %z "$shell") bytes)"
